<script setup>
import { computed, ref, watch } from "vue";
const props = defineProps({ open: Boolean, options: { type: Object, default: () => ({}) }, document: { type: Object, default: () => ({}) } }); const emit = defineEmits(["close"]);
const format = ref("Standard"); const letterhead = ref(""); const language = ref("");
watch(() => props.open, (open) => { if (open) { format.value = props.options.formats?.[0] || "Standard"; letterhead.value = props.options.letterheads?.find((row) => row.is_default)?.name || ""; language.value = props.options.default_language || "en"; } });
const baseQuery = computed(() => ({ doctype: props.document.doctype || "", name: props.document.name || "", format: format.value, letterhead: letterhead.value, no_letterhead: letterhead.value ? "0" : "1" }));
const previewQuery = computed(() => new URLSearchParams({ ...baseQuery.value, _lang: language.value }).toString());
const pdfQuery = computed(() => new URLSearchParams({ ...baseQuery.value, language: language.value }).toString());
function preview() { window.open(`/printview?${previewQuery.value}`, "_blank", "noopener"); }
function pdf() { if (!props.options.pdf_environment?.available) return; window.open(`/api/method/frappe.utils.print_format.download_pdf?${pdfQuery.value}`, "_blank", "noopener"); }
</script>
<template><Teleport to="body"><div v-if="open" class="rug-modal" role="dialog" aria-modal="true" aria-labelledby="rug-print-title" @keydown.escape="emit('close')"><button class="rug-modal__backdrop" type="button" aria-label="Close" @click="emit('close')" /><section><header><div><span class="rug-badge">Standard Frappe printing</span><h2 id="rug-print-title">Print {{ document.name }}</h2></div><button type="button" aria-label="Close" @click="emit('close')">×</button></header><div class="rug-dialog-grid"><label><span>Print format</span><select v-model="format"><option v-for="item in options.formats || []" :key="item">{{ item }}</option></select></label><label v-if="options.letterheads?.length"><span>Letterhead</span><select v-model="letterhead"><option value="">Default</option><option v-for="item in options.letterheads" :key="item.name" :value="item.name">{{ item.name }}</option></select></label><label><span>Language</span><select v-model="language"><option v-for="item in options.languages || []" :key="item.value" :value="item.value">{{ item.label }}</option></select></label></div><div v-if="!options.pdf_environment?.available" class="rug-warning"><strong>PDF download is unavailable on this server.</strong><span>The required wkhtmltopdf executable is not installed. Print preview and browser printing remain available.</span></div><footer><button type="button" @click="emit('close')">Cancel</button><button type="button" @click="preview">Print preview</button><button class="rug-primary" type="button" :disabled="!options.pdf_environment?.available" @click="pdf">Download PDF</button></footer></section></div></Teleport></template>
